using System.Security.Claims;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Taply.Models;
namespace Taply.Controllers;
[Route("admin")]
public class AdminController(TaplyDbContext db, IWebHostEnvironment env) : Controller
{
 [HttpGet("login")] public IActionResult Login()=>View();
 [HttpPost("login")] public async Task<IActionResult> Login(string email,string password) { var u=await db.Users.FirstOrDefaultAsync(x=>x.Email==email); if(u is null||new PasswordHasher<User>().VerifyHashedPassword(u,u.PasswordHash,password)==PasswordVerificationResult.Failed) { ViewBag.Error="Email hoặc mật khẩu chưa đúng."; return View(); } var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.DisplayName),new Claim(ClaimTypes.Email,u.Email)}; await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme))); return RedirectToAction(nameof(Places)); }
 [HttpPost("logout")] public async Task<IActionResult> Logout() { await HttpContext.SignOutAsync(); return RedirectToAction(nameof(Login)); }
 int OwnerId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [HttpGet("places"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> Places()=>View(await db.Places.Include(p=>p.Pages).Where(p=>p.UserId==OwnerId).OrderBy(p=>p.Name).ToListAsync());
 [HttpGet("places/{id:int}"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> Place(int id) { var p=await db.Places.Include(x=>x.Pages).Include(x=>x.SharedSections.OrderBy(s=>s.SortOrder)).FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==OwnerId); return p is null?NotFound():View(p); }
 [HttpGet("places/{id:int}/edit"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> EditPlace(int id) { var p=await db.Places.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==OwnerId);return p is null?NotFound():View(p); }
 [HttpPost("places/save"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> SavePlace(int? id,string name,string? address,string? phone,string? zalo,string? description,bool isActive=true,IFormFile? cover=null,IFormFile? logo=null) { var p=id.HasValue?await db.Places.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==OwnerId):new Place{UserId=OwnerId}; if(p is null)return NotFound(); p.Name=name; p.Address=address;p.Phone=phone;p.Zalo=zalo;p.Description=description;p.IsActive=isActive; if(string.IsNullOrWhiteSpace(p.Slug))p.Slug=await UniqueSlug(name,null); p.UpdatedAt=DateTime.UtcNow; if(cover!=null)p.CoverImageUrl=await Upload(cover);if(logo!=null)p.LogoUrl=await Upload(logo); if(id is null)db.Places.Add(p); await db.SaveChangesAsync(); return id.HasValue?RedirectToAction(nameof(Places)):RedirectToAction(nameof(Place),new{id=p.Id}); }
 [HttpPost("places/{id:int}/delete"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> DeletePlace(int id) { var p=await db.Places.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==OwnerId); if(p!=null){db.Remove(p);await db.SaveChangesAsync();} return RedirectToAction(nameof(Places)); }
 [HttpGet("pages/{id:int}/edit"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> Edit(int id) { var p=await db.Pages.Include(x=>x.Place).Include(x=>x.Sections.OrderBy(s=>s.SortOrder)).FirstOrDefaultAsync(x=>x.Id==id&&x.Place!.UserId==OwnerId); return p is null?NotFound():View(p); }
 [HttpPost("pages/save"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> SavePage(int? id,int placeId,string name,string? slug,string? subtitle,bool isActive,IFormFile? cover) { var place=await db.Places.FirstOrDefaultAsync(x=>x.Id==placeId&&x.UserId==OwnerId); if(place is null)return NotFound(); var p=id.HasValue?await db.Pages.FirstOrDefaultAsync(x=>x.Id==id&&x.PlaceId==placeId):new Page{PlaceId=placeId}; if(p is null)return NotFound(); p.Name=name;p.Slug=await UniqueSlug(string.IsNullOrWhiteSpace(slug)?name:slug,p.Id==0?null:p.Id);p.Subtitle=subtitle;p.IsActive=isActive;p.UpdatedAt=DateTime.UtcNow;if(cover!=null)p.CoverImageUrl=await Upload(cover);if(id is null)db.Pages.Add(p);await db.SaveChangesAsync();return RedirectToAction(nameof(Edit),new{id=p.Id}); }
 [HttpPost("place-sections/save"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> SavePlaceSection(int placeId,int? id,string type,string title,string? subtitle,string? icon,string? content,int sortOrder=0,bool isVisible=true) { var place=await db.Places.FirstOrDefaultAsync(x=>x.Id==placeId&&x.UserId==OwnerId);if(place is null)return NotFound();var section=id.HasValue?await db.PlaceSections.FirstOrDefaultAsync(x=>x.Id==id&&x.PlaceId==placeId):new PlaceSection{PlaceId=placeId};if(section is null)return NotFound();section.Type=type;section.Title=title;section.Subtitle=subtitle;section.Icon=string.IsNullOrWhiteSpace(icon)?"bi-info-circle":icon;section.Content=content;section.SortOrder=Math.Max(0,sortOrder);section.IsVisible=isVisible;if(id is null){section.SortOrder=sortOrder==0?await db.PlaceSections.CountAsync(s=>s.PlaceId==placeId):section.SortOrder;db.PlaceSections.Add(section);}await db.SaveChangesAsync();return RedirectToAction(nameof(Place),new{id=placeId}); }
 [HttpPost("place-sections/{id:int}/delete"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> DeletePlaceSection(int id,int placeId) { var section=await db.PlaceSections.Include(s=>s.Place).FirstOrDefaultAsync(s=>s.Id==id&&s.PlaceId==placeId&&s.Place!.UserId==OwnerId);if(section!=null){db.PlaceSections.Remove(section);await db.SaveChangesAsync();}return RedirectToAction(nameof(Place),new{id=placeId}); }
 [HttpPost("sections/save"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> SaveSection(int pageId,int? id,string type,string title,string? subtitle,string? icon,string? content,string? videoUrl,bool isVisible=true,string? contactPhone=null,string? contactZalo=null,string? contactZaloUrl=null,string? contactNote=null,string? wifiSsid=null,string? wifiPassword=null,int? sortOrder=null,IFormFile? image=null) { var page=await db.Pages.Include(x=>x.Place).FirstOrDefaultAsync(x=>x.Id==pageId&&x.Place!.UserId==OwnerId);if(page is null)return NotFound();var s=id.HasValue?await db.PageSections.FirstOrDefaultAsync(x=>x.Id==id&&x.PageId==pageId):new PageSection{PageId=pageId,SortOrder=await db.PageSections.CountAsync(x=>x.PageId==pageId)};if(s is null)return NotFound();s.Type=type;s.Title=title;s.Subtitle=subtitle;s.Icon=string.IsNullOrWhiteSpace(icon)?"bi-info-circle":icon;s.Content=type switch{"contact" when contactPhone is not null=>System.Text.Json.JsonSerializer.Serialize(new{phone=contactPhone,zalo=contactZalo,zaloUrl=contactZaloUrl,note=contactNote}),"wifi" when wifiSsid is not null=>System.Text.Json.JsonSerializer.Serialize(new{ssid=wifiSsid,password=wifiPassword}),_=>content};s.SortOrder=sortOrder??s.SortOrder;s.VideoUrl=videoUrl;s.IsVisible=isVisible;if(image!=null)s.ImageUrl=await Upload(image);if(id is null)db.PageSections.Add(s);await db.SaveChangesAsync();return RedirectToAction(nameof(Edit),new{id=pageId}); }
 [HttpPost("sections/{id:int}/delete"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> DeleteSection(int id,int pageId) { var s=await db.PageSections.Include(x=>x.Page).ThenInclude(x=>x!.Place).FirstOrDefaultAsync(x=>x.Id==id&&x.PageId==pageId&&x.Page!.Place!.UserId==OwnerId);if(s!=null){db.Remove(s);await db.SaveChangesAsync();}return RedirectToAction(nameof(Edit),new{id=pageId}); }
 [HttpPost("sections/order"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> Order(int pageId,[FromBody] int[] ids) { var sections=await db.PageSections.Include(s=>s.Page).ThenInclude(p=>p!.Place).Where(s=>s.PageId==pageId&&s.Page!.Place!.UserId==OwnerId).ToListAsync();for(int i=0;i<ids.Length;i++){var s=sections.FirstOrDefault(x=>x.Id==ids[i]);if(s!=null)s.SortOrder=i;}await db.SaveChangesAsync();return Ok(); }
 [HttpPost("upload"),Microsoft.AspNetCore.Authorization.Authorize] public async Task<IActionResult> UploadEndpoint(IFormFile file) => Ok(new{url=await Upload(file)});
 async Task<string> Upload(IFormFile f) { var ext=Path.GetExtension(f.FileName).ToLowerInvariant();if(f.Length>5*1024*1024||!new[]{".jpg",".jpeg",".png",".webp"}.Contains(ext))throw new InvalidOperationException("Ảnh không hợp lệ hoặc vượt quá 5 MB.");var dir=Path.Combine(env.WebRootPath,"uploads",OwnerId.ToString());Directory.CreateDirectory(dir);var name=Guid.NewGuid()+ext;await using var stream=System.IO.File.Create(Path.Combine(dir,name));await f.CopyToAsync(stream);return $"/uploads/{OwnerId}/{name}"; }
 async Task<string> UniqueSlug(string s,int? except) { var root=PublicController.Slug(s);if(root.Length==0)root="trang";var candidate=root;var n=2;while(await db.Pages.AnyAsync(x=>x.Slug==candidate&&x.Id!=except)||await db.Places.AnyAsync(x=>x.Slug==candidate&&(!except.HasValue)))candidate=$"{root}-{n++}";return candidate; }
}
